/**
 * Your interests — genres + adventurous / depth dials.
 * Clock mix lane / vibes / scenes stay automatic.
 */
import { useEffect, useState } from "react";
import { fontDisplay, fontMono, color, radius, glass, aluminumGradient, BTN_PRIMARY } from "../../theme";
import { CANONICAL_GENRES, migratePreferredGenres } from "../../lib/genres";
import {
  ADVENTUROUS_LABELS,
  DEPTH_LABELS,
  TASTE_AXIS_DEFAULT,
  normalizeTasteProfile,
} from "../../lib/tasteProfile";
import TasteAxisSlider from "./TasteAxisSlider";

export default function GenreTasteSheet({
  onClose,
  selectedGenres = [],
  adventurous = TASTE_AXIS_DEFAULT,
  depth = TASTE_AXIS_DEFAULT,
  onSave,
  onClearGenreFocus = null,
  genreFocus = null,
  onBuildSet = null,
}) {
  const initial = normalizeTasteProfile({
    genres: migratePreferredGenres(selectedGenres),
    adventurous,
    depth,
  });
  const [genres, setGenres] = useState(initial.genres);
  const [adv, setAdv] = useState(initial.adventurous);
  const [dep, setDep] = useState(initial.depth);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const next = normalizeTasteProfile({
      genres: migratePreferredGenres(selectedGenres),
      adventurous,
      depth,
    });
    setGenres(next.genres);
    setAdv(next.adventurous);
    setDep(next.depth);
  }, [selectedGenres, adventurous, depth]);

  const selected = new Set(genres);

  async function persist(nextGenres, nextAdv, nextDep) {
    if (!onSave) return;
    setSaving(true);
    try {
      await onSave({
        genres: nextGenres,
        adventurous: nextAdv,
        depth: nextDep,
      });
    } finally {
      setSaving(false);
    }
  }

  function toggleGenre(g, nextOn) {
    const arr = CANONICAL_GENRES.filter((x) =>
      x === g ? nextOn : selected.has(x)
    );
    setGenres(arr);
    persist(arr, adv, dep);
  }

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 100, overflow: "hidden" }}>
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          background: aluminumGradient(),
        }}
      />
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          inset: 0,
          background:
            "radial-gradient(ellipse at 50% 0%, rgba(169,199,228,0.06) 0%, transparent 48%)",
        }}
      />

      <div
        className="hide-scroll"
        style={{
          position: "relative",
          zIndex: 1,
          height: "100%",
          overflowY: "auto",
          display: "flex",
          flexDirection: "column",
        }}
      >
        <div style={{
          display: "flex",
          justifyContent: "flex-end",
          padding: "20px 20px 8px",
          flexShrink: 0,
        }}>
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            style={{
              background: glass.fillStrong,
              border: `1px solid ${glass.borderSoft}`,
              borderRadius: radius.md,
              width: 36,
              height: 36,
              cursor: "pointer",
              color: color.muted,
              fontSize: 18,
              lineHeight: 1,
              boxShadow: `inset 0 1px 0 ${glass.highlight}`,
            }}
          >
            ×
          </button>
        </div>

        <div style={{
          padding: "8px 22px 48px",
          maxWidth: 520,
          margin: "0 auto",
          width: "100%",
          animation: "rise 0.45s cubic-bezier(0.22,1,0.36,1) both",
        }}>
          <div style={{
            fontSize: 11,
            fontWeight: 650,
            letterSpacing: 1.8,
            textTransform: "uppercase",
            color: color.accent,
            fontFamily: fontMono,
            marginBottom: 10,
          }}>
            Your interests
          </div>
          <h2 style={{
            margin: 0,
            fontSize: 34,
            fontWeight: 700,
            letterSpacing: -1,
            color: color.ink,
            fontFamily: fontDisplay,
            marginBottom: 10,
          }}>
            Edit your taste
          </h2>
          <p style={{
            margin: "0 0 24px",
            fontSize: 15,
            color: color.body,
            lineHeight: 1.45,
            maxWidth: 360,
          }}>
            Genres and dials steer what we pick for you. Changes save as you go.
            {saving ? " Saving…" : ""}
          </p>

          {genreFocus && onClearGenreFocus && (
            <div style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 12,
              marginBottom: 24,
              padding: "12px 0",
              borderTop: `1px solid ${color.line}`,
              borderBottom: `1px solid ${color.line}`,
            }}>
              <div>
                <div style={{
                  fontSize: 11,
                  fontWeight: 650,
                  letterSpacing: 1.2,
                  textTransform: "uppercase",
                  color: color.faint,
                  fontFamily: fontMono,
                  marginBottom: 4,
                }}>
                  Playing now
                </div>
                <div style={{ fontSize: 17, fontWeight: 650, fontFamily: fontDisplay }}>
                  {genreFocus}
                </div>
              </div>
              <button
                type="button"
                onClick={onClearGenreFocus}
                style={{
                  padding: "8px 14px",
                  borderRadius: radius.md,
                  border: `1px solid ${color.lineStrong}`,
                  background: glass.fillStrong,
                  color: color.body,
                  fontSize: 13,
                  fontWeight: 600,
                  cursor: "pointer",
                  boxShadow: `inset 0 1px 0 ${glass.highlight}`,
                }}
              >
                Clear
              </button>
            </div>
          )}

          <TasteAxisSlider
            id="sheet-adventurous"
            title={ADVENTUROUS_LABELS.title}
            hint={ADVENTUROUS_LABELS.hint}
            lowLabel={ADVENTUROUS_LABELS.low}
            highLabel={ADVENTUROUS_LABELS.high}
            value={adv}
            onChange={(next) => {
              setAdv(next);
              persist(genres, next, dep);
            }}
          />
          <TasteAxisSlider
            id="sheet-depth"
            title={DEPTH_LABELS.title}
            hint={DEPTH_LABELS.hint}
            lowLabel={DEPTH_LABELS.low}
            highLabel={DEPTH_LABELS.high}
            value={dep}
            onChange={(next) => {
              setDep(next);
              persist(genres, adv, next);
            }}
          />

          <div style={{
            fontSize: 11,
            fontWeight: 650,
            letterSpacing: 1.4,
            textTransform: "uppercase",
            color: color.accent,
            fontFamily: fontMono,
            margin: "8px 0 14px",
          }}>
            Genres
          </div>

          <GenreToggleList
            selected={selected}
            onToggle={toggleGenre}
          />

          {onBuildSet && (
            <button
              type="button"
              onClick={onBuildSet}
              style={{
                ...BTN_PRIMARY,
                marginTop: 28,
                borderRadius: radius.xl,
                fontSize: 15,
                fontWeight: 650,
              }}
            >
              Build a set
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

function GenreToggleList({ selected, onToggle }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      {CANONICAL_GENRES.map((g) => {
        const on = selected.has(g);
        return (
          <button
            key={g}
            type="button"
            onClick={() => onToggle(g, !on)}
            aria-pressed={on}
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              gap: 12,
              padding: "14px 14px",
              background: on
                ? `
                  linear-gradient(165deg, rgba(48,53,62,0.9) 0%, rgba(25,28,34,0.7) 100%)
                `
                : `
                  linear-gradient(165deg, rgba(32,36,43,0.65) 0%, rgba(28,32,38,0.35) 100%)
                `,
              border: `1px solid ${on ? glass.border : glass.borderSoft}`,
              borderRadius: radius.lg,
              boxShadow: on
                ? `inset 0 1px 0 ${glass.highlight}, ${glass.shadowSoft}`
                : `inset 0 1px 0 ${glass.highlight}`,
              backdropFilter: glass.blurSoft,
              WebkitBackdropFilter: glass.blurSoft,
              cursor: "pointer",
              textAlign: "left",
              color: color.ink,
            }}
          >
            <span style={{
              fontSize: 17,
              fontWeight: 600,
              fontFamily: fontDisplay,
              color: on ? color.accent : color.ink,
            }}>
              {g}
            </span>
            <span style={{
              width: 22,
              height: 22,
              borderRadius: radius.sm,
              border: on ? "none" : `1px solid ${color.lineStrong}`,
              background: on ? color.accent : "transparent",
              color: color.onAccent,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: 12,
              fontWeight: 700,
              flexShrink: 0,
            }} aria-hidden="true">
              {on ? "✓" : ""}
            </span>
          </button>
        );
      })}
    </div>
  );
}
